package com.yuegang.zhihui.common.web;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.regex.*;import org.apache.commons.logging.*;import org.springframework.web.filter.OncePerRequestFilter;
/** Emits immutable, body-free mutation audit records. Credentials and personal payloads are never read. */
public final class AuditLoggingFilter extends OncePerRequestFilter{private static final Log LOG=LogFactory.getLog("ygh.audit");private static final Pattern ID=Pattern.compile("[0-9]{1,20}");@Override protected boolean shouldNotFilter(HttpServletRequest r){return switch(r.getMethod()){case"POST","PUT","PATCH","DELETE"->false;default->true;};}@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws ServletException,IOException{boolean failed=false;try{c.doFilter(r,p);}catch(ServletException|IOException|RuntimeException e){failed=true;throw e;}finally{String user=r.getHeader("X-YGH-User-Id");if(user==null||!ID.matcher(user).matches())user="service-or-anonymous";String trace=TraceIdResolver.resolve(r);LOG.info("business_mutation userId="+user+" method="+r.getMethod()+" path="+r.getRequestURI()+" status="+(failed?500:p.getStatus())+" traceId="+trace);}}}
